const binaryKey = Object.keys($input.item.binary)[0];
const pdfBuffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
const base64PDF = pdfBuffer.toString('base64');

const systemPrompt = `You are extracting fields from a Pre-Approval Letter PDF for a mortgage loan. Extract EXACTLY these fields and return valid JSON only — no markdown, no explanation.

Required fields:
- first_name (borrower first name only)
- full_name (borrower full legal name)
- borrower_email (if present in the letter, otherwise null)
- purchase_price (maximum approved purchase price — dollar amount, numbers only)
- loan_amount (maximum approved loan amount — dollar amount, numbers only)
- loan_type (Conventional, FHA, VA, USDA, etc.)
- expiration_date (letter expiration date — YYYY-MM-DD format)
- property_type (Single Family, Condo, Townhome, etc. — null if not specified)

Return JSON like:
{"first_name":"Maria","full_name":"Maria Johnson","borrower_email":null,"purchase_price":"450000","loan_amount":"360000","loan_type":"Conventional","expiration_date":"2026-03-31","property_type":"Single Family"}`;

const userPrompt = 'Extract the pre-approval letter fields from this PDF. Return ONLY the JSON object, nothing else.';

const claudeBody = {
  model: 'claude-sonnet-4-5-20251022',
  max_tokens: 2048,
  system: systemPrompt,
  messages: [{
    role: 'user',
    content: [
      { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: base64PDF } },
      { type: 'text', text: userPrompt }
    ]
  }]
};

return [{ json: { claudeBody, webhookBody: $('Webhook').item.json.body } }];

const raw = $json.content[0].text;
let pa;
try {
  const jsonMatch = raw.match(/\{[\s\S]*\}/);
  pa = JSON.parse(jsonMatch ? jsonMatch[0] : raw);
} catch (e) {
  throw new Error('Failed to parse Claude response as JSON: ' + raw.substring(0, 200));
}

const val = (v) => (v !== null && v !== undefined && v !== '') ? v : '[MISSING]';
const fmt$ = (n) => {
  if (!n) return '[MISSING]';
  return '$' + Number(n).toLocaleString('en-US', { minimumFractionDigits: 0, maximumFractionDigits: 0 });
};
const fmtDate = (d) => {
  if (!d) return '[MISSING]';
  return new Date(d + 'T00:00:00').toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
};

return [{ json: {
  first_name: val(pa.first_name),
  full_name: val(pa.full_name),
  borrower_email: pa.borrower_email || '[BORROWER_EMAIL]',
  purchase_price: fmt$(pa.purchase_price),
  loan_amount: fmt$(pa.loan_amount),
  loan_type: val(pa.loan_type),
  expiration_date: fmtDate(pa.expiration_date),
  property_type: pa.property_type || null,
  webhookBody: $('Build Claude Request').item.json.webhookBody
}}];

const f = $json;

const subject = `\ud83c\udf89 You're Pre-Approved, ${f.first_name}! Here's What Happens Next`;

